import { parseExpression } from "./parse-expression.ts";
import { Expression } from "../../parse/class/expression.ts";
import { Scope } from "../../parse/class/scope.ts";
import { Statement } from "../../parse/class/statement.ts";
import { Text } from "../../parse/class/text.ts";
import type { StatementCallback } from "../type/statement-callback.ts";
import type { Variables } from "../type/variables.ts";
import type { CoreNode } from "../../parse/type/core-node.ts";

export function resolve(
  scope: Scope,
  upperVariables: Variables,
  statementCallback: StatementCallback
): string {
  // combine given variables and scope's variables
  const variables: Variables = {
    ...upperVariables,
    ...scope.variables
  };
  
  const resolved: (Expression | Text)[] = [];
  
  for (const item of scope) {
    let node: CoreNode = item;
    while (node instanceof Statement) {
      const statement = statementCallback(node, variables);
      // if node[] instead of node...
      if (statement instanceof Array && !(statement instanceof Scope))
        node = Scope.fromIterable(statement);
      else
        node = statement;
    }

    if (node instanceof Scope) {
      // recurse for deeper scope
      const string = resolve(node, {
        ...variables,
        ...node.variables
      }, statementCallback);
      node = new Text(string);
    }

    resolved.push(node);
  }
  
  const templates: Text[] = [];
  
  for (const node of resolved) {
    const result: Text = node instanceof Expression
      ? new Text(parseExpression(node.content, variables))
      : node;
    
    templates.push(result);
  }
  
  const final = templates.join("");
  
  return final;
}
